from layout import *

def packets():
    page('Отбор строк из истории агента','Стоит ли запоминать единицы редактирования целиком',
         'Если замена требует несколько соседних строк, польза возникает лишь после сохранения всего фрагмента. Проверили, можно ли предсказать такую потребность по прошлым действиям.')
    p('В открытых траекториях SWE-smith после каждых четырёх вызовов инструментов искусственно обрываем контекст. Для первого принятого редактирования среди ближайших четырёх действий проверяем, содержит ли память исходную строку целиком по правильному пути. Агент видит только строки и действия до прерывания. При выборе признаков доступны давность чтения, положение в просмотренном участке, тип строки, предшествующие правки и пересечение с условием.')
    p('Видимый текст делим на страницы по 12 строк. На других репозиториях оцениваем вероятность того, что будущая операция потребует одну, две или три соседние страницы. Строим сообщение, выбирая блоки с максимальным приростом вероятности полного покрытия на добавленный токен. Контроль с теми же вероятностями начисляет ценность каждой странице отдельно. Недавние строки образуют более простой и часто более сильный контроль.')
    a=J('packets/results.json')['results']
    tbl(['Что класть в память','256 токенов','512 токенов','1 024 токена'],[[s,*[n(a[str(k)]['metrics'][m]['hit']) for k in (256,512,1024)]] for s,m in [('Хвост после сброса','reset_tail'),('Недавний хвост с учётом правок','rebased_tail'),('Локальный непрерывный участок','latest_contiguous'),('Страницы независимо','marginal'),('Совместно необходимые страницы','joint')]], [7.1,3.3,3.3,3.4])
    p('Числа в таблице — попадания из 3 405 окон на 986 задачах. В первый тест вошли 1 013 траекторий из 16 репозиториев, а в обучение — 1 350 траекторий из 51 другого репозитория. Предсказания зафиксированы до сверки с будущим редактированием.')
    h('Первичный результат')
    p('При 512 токенах получено 852/3 405 против 796/3 405 у заранее выбранного хвоста с учётом правок. Разность +1,64 п.п., 95% ДИ по репозиториям от +0,55 до +3,37. При сокращении бюджета до 256 знак меняется. Тот же контроль даёт 346 попаданий, новый метод — 338, а хвост после сброса — 375.')
    source('Публичный корпус и схема сбора записей инструментов · SWE-smith',ar('2504.21798'))

def transfer_packets():
    page('Проверка на других задачах','Как изменился результат при обратном переносе',
         'На второй выборке преимущество над простым хвостом сохранилось при 1 024 токенах. На основном бюджете 512 интервал допускает как небольшой проигрыш, так и выигрыш.')
    p('После первой серии поменяли роли репозиториев. Новый экземпляр модели обучили на 16 проектах первой проверки. Для теста взяли ранее не использованные задачи из остальных 51 проекта. Из первой выборки заранее выбрали лучший простой контроль для каждого бюджета. Кроме двух правил хвоста проверили пары и тройки соседних страниц, определения Python и тот же алгоритм с необученным распределением вероятностей.')
    a=J('packets/transfer/results.json')['results'];rows=[]
    for k,d in a.items():
        ctrl=d['validated_simple_control'];r=d['B_joint_contrasts'][ctrl]
        dt=r['ci95'];rows.append([n(int(k)),n(d['B_metrics']['joint']['hit']),n(d['B_metrics'][ctrl]['hit']),str(r['wins'])+' / '+str(r['losses']),pp(r['difference'],2),'['+pp(dt[0],2)+'; '+pp(dt[1],2)+']'])
    rows.sort(key=lambda v:int(v[0].replace(' ','')))
    tbl(['Бюджет','Совместно','Контроль','W / L','Δ, п.п.','95% ДИ, п.п.'],rows,[2.2,3.0,2.85,2.8,2.2,4.05],True)
    p('Знаменатель — 4 190 окон, 1 250 задач с принятыми правками. Контроль при 256 — хвост после сброса, при 512 и 1 024 — хвост с учётом правок. W/L — число окон, в которых выиграл или проиграл попарный выбор. Доверительный интервал сохраняет зависимость окон внутри одного репозитория.')
    h('Откуда мог прийти выигрыш')
    p('При 1 024 токенах независимое начисление ценности даёт 1 741 попадание, та же модель с совместной оценкой — 1 910. Необученная равномерная альтернатива с тем же упаковщиком даёт 1 771. При 512 эти значения составили 1 007, 1 137 и 1 043. Расширение хвоста фиксированными соседями не стало лучшим простым правилом на первой выборке.')
    p('Эффект против одного фиксированного контроля — хвоста с учётом правок. Шкала в процентных пунктах, отрезки обозначают 95% ДИ по репозиториям.','Caption')
    doc.add_picture(str(HERE/'budget_effect.png'),width=Cm(16.3))
    h('Можно ли переносить токены между обращениями')
    p('На третьей выборке из 649 новых задач проверили расходуемый по мере работы бюджет. Из 2 108 принятых замен правило ожидаемой ценности сохранило 539 нужных фрагментов против 543 у постоянных 512 токенов. Токены на всех 4 277 обращениях — 2 003 433 против 2 022 625 (−0,95%). Циклическое правило дало 422 попадания. Для данного способа предсказания переменный бюджет не окупился.')

def serbench():
    page('Опубликованный бенчмарк','Восстановление полного комплекта свидетельств на SERBench',
         'Линейная модель на публичном Cal500 опередила официальный стартовый BM25. Добавление отдельного предсказателя совместной полезности не улучшило первичную метрику.')
    p('Работа Feng et al. размечает, какие группы сведений необходимы для решения в данном состоянии. MSS-Complete@k равно единице, только если в первых k возвращённых объектах покрыта каждая требуемая группа. Официальный оценщик применили ко всем 500 состояниям Cal500. Для обучения использовали пять непересекающихся по репозиториям фолдов (241 задача, 174 репозитория).')
    t=J('serbench/results.json')['upstream']
    tbl(['Метод на публичном Cal500','Полное покрытие @5','Полное покрытие @8'],[[name,perc(t[k]['mss_complete@5']),perc(t[k]['mss_complete@8'])] for name,k in [('Официальный BM25 из SDK','sdk_bm25'),('Независимая модель объектов','independent'),('Та же модель с разнообразием','diversity'),('Добавлены оценки пар объектов','pair_completion')]], [7.6,4.75,4.75])
    p('Обе обучаемые схемы используют одни лексические и структурные признаки. Одна обучается предсказывать вхождение отдельного объекта в требования, другая также оценивает, принадлежат ли два объекта разным необходимым группам. Для @5 влияние оценки пар равно −0,6 п.п., 95% ДИ по репозиториям от −3,70 до +2,47. Для @8 — +2,2 п.п., от −1,03 до +5,35. Контроль разнообразия на @5 немного сильнее обеих моделей.')
    p('В разведочном срезе по числу групп наблюдается разнонаправленный эффект. На 258 состояниях с несколькими группами оценка пар полностью закрыла 26 случаев против 21. На 242 состояниях с одной группой она закрыла 99 против 107. Заранее допустимый способ распознавать эти группы без ответа ещё предстоит проверить.')
    h('Как читать цифры авторской статьи')
    p('Для закрытого Test500 из 45 других репозиториев зафиксированы прогнозы для 500 состояний. Эталонные группы закрыты, оценка и отправка на сервер не выполнялись. Опубликованные авторами 73,0% при пяти и 80,6% при восьми объектах относятся к Test500, семантическому MSS-Complement и авторскому лимиту 6 144 токена. Локальный протокол SDK на Cal500 ограничивает число объектов. Дополнительный расчёт с ограничением в токенах приведён на следующей странице.')
    source('Авторский оценщик и публичные входы SERBench','https://github.com/LordTARN1SHED/SERBench/tree/8c27a88e48dcbcd4a5745573c95937a4740f4406')
